            <h3 className="text-xl font-bold text-slate-800 mb-4">Eliminar Cuenta</h3>
            {deleteStep === 'transfer' ? (
                <>
                    <p className="text-sm text-slate-600 mb-6">Debes traspasar la propiedad de <b>{pets[0]?.name}</b>.</p>
