  accessToken?: string
): Promise<AIAnalysisResult> => {
  const ai = getAIClient();
  const now = new Date();

  // Si hay imágenes, el textInput contiene los metadatos EXIF extraídos por el cliente
  const promptText = imageParts.length > 0 
