                     <div className="mb-6"><label className="block text-sm font-medium text-slate-700 mb-2">Mascota Activa</label>
                        <select value={currentPet?.id || ''} onChange={(e) => { const s = pets.find(p => p.id === e.target.value); if(s) setCurrentPet(s); }} className="w-full p-3 rounded-xl border border-slate-200 bg-white">
                            {pets.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                        </select>
                     </div>
                     {currentPet && session?.user && <TeamManager settings={settings} currentPet={currentPet} currentUserId={session.user.id} accessToken={session.access_token}/>}
                     {currentPet?.owner_id === session?.user?.id && <MigrationPanel supabaseSettings={settings} currentPet={currentPet} currentUser={session?.user} accessToken={session.access_token}/>}
                     <div className="mt-10 border-t pt-6">
                        <button onClick={handleLogout} className="w-full py-3 bg-slate-100 text-slate-600 rounded-xl font-bold mb-3">Cerrar Sesión</button>
                        <button onClick={() => { setDeleteStep('initial'); setShowDeleteModal(true); }} className="w-full py-2 bg-red-600 text-white rounded-lg font-bold text-xs">Eliminar Cuenta</button>
                     </div>
                 </div>
            )}
            {view === 'add' && (
                <div className="flex-1 overflow-y-auto p-4 bg-slate-50 h-full relative">
                    {inputMethod === 'menu' && (
                        <div className="flex flex-col items-center justify-center h-full space-y-6 animate-fade-in-up">
                             <h2 className="text-2xl font-bold text-slate-800 mb-4">Nuevo Registro</h2>
                             <button onClick={() => setInputMethod('voice')} className="w-full py-6 bg-white border-2 border-blue-100 rounded-3xl shadow-sm flex flex-col items-center gap-3 active:scale-95 transition-all"><div className="p-4 bg-blue-100 text-blue-600 rounded-full"><Icons.Mic className="w-8 h-8" /></div><span className="font-bold text-slate-700">Nota de Voz (IA)</span></button>
                             <label className="w-full py-6 bg-white border-2 border-purple-100 rounded-3xl shadow-sm flex flex-col items-center gap-3 active:scale-95 transition-all cursor-pointer"><div className="p-4 bg-purple-100 text-purple-600 rounded-full"><Icons.Camera className="w-8 h-8" /></div><span className="font-bold text-slate-700">Analizar Foto (IA)</span><input type="file" accept="image/*" className="hidden" onChange={handleImageUpload} /></label>
                             <button onClick={() => setInputMethod('manual')} className="w-full py-6 bg-white border-2 border-slate-100 rounded-3xl shadow-sm flex flex-col items-center gap-3 active:scale-95 transition-all"><div className="p-4 bg-slate-100 text-slate-600 rounded-full"><Icons.CheckSquare className="w-8 h-8" /></div><span className="font-bold text-slate-700">Manual</span></button>
                             <button onClick={() => setView('home')} className="mt-8 text-slate-400 font-medium">Cancelar</button>
                        </div>
                    )}
                    {inputMethod === 'voice' && <div className="h-full flex flex-col items-center justify-center"><h3 className="text-xl font-bold text-slate-700 mb-8">Grabando...</h3><AudioRecorder onAudioCaptured={handleAudioCaptured} isProcessing={aiProcessing} /><button onClick={() => setInputMethod('menu')} className="mt-12 text-slate-400">Cancelar</button></div>}
                    {inputMethod === 'manual' && <EventForm initialData={draftEvent} onSubmit={handleEventSubmit} onCancel={()=>setView('home')} onDelete={draftEvent?.id?()=>handleDeleteEvent(draftEvent as DogEvent):undefined} canEdit={permissions.can_edit !== 'none'} canDelete={permissions.can_delete !== 'none'}/>}
                    {aiProcessing && <div className="absolute inset-0 bg-white/80 z-50 flex flex-col items-center justify-center backdrop-blur-sm"><div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin mb-4"></div><p className="font-bold text-slate-700">Analizando con IA...</p></div>}
                </div>
            )}
            <Navbar currentView={view} setView={setView} hasUnread={hasUnreadMessages} />
            {fullScreenImage && <ImageViewer src={fullScreenImage} onClose={() => setFullScreenImage(null)} />}
            {showDeleteModal && renderDeleteModal()}
         </div>}
    </>
  );

  async function handleEventSubmit(event: DogEvent) {
    if (!currentPet || !session) return;
    setIsLoading(true);
    event.petId = currentPet.id;
    if (!event.userId) event.userId = session.user.id;
    const res = await saveEventToSupabase(event, settings, session.access_token);
    if (res.success) { setView('home'); fetchEvents(true); }
    setIsLoading(false);
  }

  async function handleDeleteEvent(event: DogEvent) {
    if (!session) return;
    const res = await deleteEvent(event.id, event.photoUrl, settings, session.access_token);
    if (res.success) { setView('home'); fetchEvents(true); }
  }
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AIAnalysisResult, HealthStatus, RecordType, SupabaseSettings, DogEvent, ChatMessage } from "../types";

// Siempre usar gemini-3-flash-preview para tareas de texto básico y multimodales
const MODEL_NAME = 'gemini-3-flash-preview';

const SYSTEM_INSTRUCTION = `
Eres un asistente veterinario experto. Tu tarea es analizar imágenes, audios o textos de un dueño de perro.

REGLAS DE CLASIFICACIÓN VISUAL (CRÍTICO):
Analiza la imagen adjunta y clasifícala estrictamente en uno de estos tipos de 'recordType':
- 'Caca': Excrementos. OBLIGATORIO: Evalúa consistencia (poopScore 1-10).
  REGLA DE TÍTULO PARA CACA: El 'title' DEBE ser un resumen corto que empiece por la calificación.
  Usa esta escala estricta basada en el poopScore:
  * 0-2: "Muy mala"
  * 3-4: "Mala"
  * 5-6: "Regular"
  * 7-8: "Buena"
  * 9-10: "Excelente"
  Ejemplo de título: "Buena - Heces firmes y color normal".
- 'Comida': Cuencos, sacos de pienso, comida casera.
- 'Medicamento': Pastillas, jarabes, inyecciones, cajas de fármacos.
- 'Veterinario': Consultas, veterinarios, clínicas.
- 'Comportamiento': Acciones del perro, estado de ánimo.
- 'Resumen': Resúmenes semanales o notas generales.
- 'Analiticas': Informes médicos, analíticas de sangre, facturas.
- 'Vómito': Manchas de fluido estomacal, comida devuelta.
- 'Coche': Perro en el coche, transportín, viajes.
- 'Incidente': Heridas, accidentes, cosas inusuales.

REGLA DE FECHA Y HORA (MANDATORIO):
1. Si recibes un bloque "METADATOS_FOTO", DEBES usar esa fecha y hora EXACTAMENTE para los campos 'date' y 'time'. Es la fecha real de captura contenida en el EXIF.
2. Solo si NO hay metadatos específicos de foto, usa la fecha actual proporcionada.
3. El formato de 'date' debe ser YYYY-MM-DD y 'time' HH:MM.
`;

const CONSULTANT_INSTRUCTION = `
Eres un asistente veterinario inteligente. Responde dudas sobre el historial del perro basándote en los eventos proporcionados.
`;

const getAIClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey || apiKey.length < 5) {
    throw new Error("API Key no configurada.");
  }
  return new GoogleGenAI({ apiKey });
};

// Esquema común para todas las respuestas de análisis
const ANALYSIS_SCHEMA = {
  type: Type.OBJECT,
  properties: {
    title: { type: Type.STRING },
    recordType: { type: Type.STRING, enum: Object.values(RecordType) },
    healthStatus: { type: Type.STRING, enum: Object.values(HealthStatus), nullable: true },
    description: { type: Type.STRING },
    weight: { type: Type.NUMBER, nullable: true },
    date: { type: Type.STRING, nullable: true },
    time: { type: Type.STRING, nullable: true },
    poopScore: { type: Type.INTEGER, nullable: true }
  },
  required: ["title", "recordType", "date", "time"]
};

export const analyzeInput = async (
  textInput: string,
  imageParts: string[] = [],
  settings: SupabaseSettings,
  accessToken?: string
): Promise<AIAnalysisResult> => {
  const ai = getAIClient();
  const now = new Date();

  const promptText = imageParts.length > 0 
    ? `METADATOS_FOTO: ${textInput}`
    : `INSTRUCCIÓN: ${textInput}\nFECHA_ACTUAL: ${now.toLocaleString('es-ES')}`;

  const response = await ai.models.generateContent({
    model: MODEL_NAME,
    contents: [{
      parts: [
        { text: promptText },
        ...imageParts.map(data => ({
          inlineData: { mimeType: 'image/jpeg', data: data.split(',')[1] || data }
        }))
      ]
    }],
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
      responseMimeType: "application/json",
      responseSchema: ANALYSIS_SCHEMA
    }
  });

  if (!response.text) throw new Error("La IA no devolvió contenido.");
  return JSON.parse(response.text);
};

export const analyzeImage = async (imageBase64: string, settings: SupabaseSettings, metadataHint: string = "", accessToken?: string): Promise<AIAnalysisResult> => {
    return analyzeInput(metadataHint, [imageBase64], settings, accessToken);
};

export const analyzeAudio = async (audioBase64: string, settings: SupabaseSettings, accessToken?: string): Promise<AIAnalysisResult> => {
    const ai = getAIClient();
    const now = new Date();
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: [
        {
          parts: [
            { inlineData: { mimeType: "audio/mp3", data: audioBase64 } },
            { text: `Hoy es ${now.toLocaleString('es-ES')}. Transcribe este audio y extrae los datos del evento del perro siguiendo las reglas de clasificación.` }
          ]
        }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ANALYSIS_SCHEMA
      }
    });
    if (!response.text) throw new Error("Audio vacío.");
    return JSON.parse(response.text);
};

export const analyzeFile = async (base64Data: string, mimeType: string, settings: SupabaseSettings, accessToken?: string): Promise<AIAnalysisResult> => {
    const ai = getAIClient();
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: [
        {
          parts: [
            { inlineData: { mimeType, data: base64Data.split(',')[1] || base64Data } },
            { text: "Analiza este documento veterinario." }
          ]
        }
      ],
      config: {
        systemInstruction: SYSTEM_INSTRUCTION,
        responseMimeType: "application/json",
        responseSchema: ANALYSIS_SCHEMA
      }
    });
    if (!response.text) throw new Error("Archivo vacío.");
    return JSON.parse(response.text);
};

export const consultAssistant = async (history: ChatMessage[], settings: SupabaseSettings, petId: string, accessToken?: string): Promise<{ text: string, events?: DogEvent[] }> => {
    const ai = getAIClient();
    const contents = history.map(msg => ({
        role: msg.role === 'assistant' ? 'model' : 'user',
        parts: [{ text: msg.text }]
    }));

    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents,
      config: { systemInstruction: CONSULTANT_INSTRUCTION }
    });

    return { text: response.text || "No tengo respuesta." };
};

export const detectTaskFromNote = async (
  text: string,
  mentionedUsers: { id: string, name: string }[],
  settings: SupabaseSettings,
  accessToken?: string
): Promise<{ title: string; assignedToId: string | null } | null> => {
  const ai = getAIClient();
  const prompt = `Nota: "${text}". Usuarios: ${JSON.stringify(mentionedUsers)}. ¿Es tarea? Responde JSON {isTask, title, assignedToId}`;

  try {
    const response = await ai.models.generateContent({
      model: MODEL_NAME,
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isTask: { type: Type.BOOLEAN },
            title: { type: Type.STRING, nullable: true },
            assignedToId: { type: Type.STRING, nullable: true }
          },
          required: ["isTask"]
        }
      }
    });

    const result = JSON.parse(response.text || '{}');
    if (result.isTask && result.title) {
      return { title: result.title, assignedToId: result.assignedToId };
    }
  } catch (error) {
    console.error("Task detection error:", error);
  }
  return null;
};
